('op-catalogo-amplio','Maneja catálogo amplio de productos','¿Maneja una variedad amplia de productos?','confirmada'),
('op-compra-proveedores','Compra a proveedores de forma recurrente','¿Compra mercadería o insumos a proveedores de forma recurrente?','confirmada'),
('op-precios-mueven','Sus precios se mueven según demanda o temporada','¿Sus precios cambian según demanda, temporada o mercado?','confirmada'),
