insert into public.necesidad (clave,nombre,descripcion,pregunta_confirmacion,estado) values
('nec-fuera-horario','Pierde ventas fuera de horario','Consultas que llegan cuando no hay nadie para responder.','¿Le llegan consultas fuera del horario de atención que hoy quedan sin responder?','confirmada'),
('nec-agenda-desordenada','Agenda desordenada','Turnos, citas o reservas coordinados a mano, con choques y olvidos.','¿Coordina turnos o reservas a mano, por mensajes sueltos?','confirmada'),
('nec-no-sabe-reponer','No sabe qué reponer','Compra por costumbre, sin cruzar lo que realmente se vende.','¿Decide qué comprar más por costumbre que por datos de venta?','confirmada'),
('nec-pierde-mercaderia','Se le pierde mercadería','Diferencias entre lo comprado, lo vendido y lo que queda, sin explicación.','¿Nota diferencias entre lo que compra, lo que vende y lo que queda en stock?','confirmada'),
('nec-reparto-ineficiente','Reparto ineficiente','Rutas armadas por orden de llegada del pedido, no por cercanía.','¿El repartidor arma la ruta a criterio propio, sin optimizarla?','confirmada'),
('nec-no-sabe-que-pasa-en-el-local','No sabe qué pasa en el local','Sin forma de saber cuándo hay más movimiento o dónde se pierden clientes.','¿Tiene forma de saber en qué horarios y zonas del local hay más movimiento?','confirmada'),
('nec-precios-desactualizados','Precios desactualizados frente al mercado','El precio queda fijo mientras la demanda, el stock o la competencia cambian.','¿Hace cuánto no revisa precios frente a la competencia o la rotación real?','confirmada'),
('nec-sin-memoria-del-negocio','No tiene memoria del negocio','Sin historial propio para comparar un día, una semana o un mes con otro.','¿Lleva un registro diario de ventas que le permita comparar períodos?','confirmada'),
('nec-no-cotiza-rapido','Tarda en armar una cotización','Cada cotización se arma desde cero, sin una guía de preguntas.','¿Cada cotización nueva la arma desde cero, sin una guía previa?','confirmada'),
('nec-no-vende-online','No tiene canal de venta online','Todo lo que se vende depende de que el cliente pase por el local.','¿Hoy vende exclusivamente en el local, sin canal online?','confirmada'),
('nec-no-ve-el-mercado','No sabe qué hace la competencia','Decide precios y compras sin mirar qué mueve el mercado.','¿Sigue de cerca lo que hacen sus competidores directos?','confirmada'),
('nec-no-controla-espacios','No controla sus espacios en tiempo real','No sabe, en el momento, qué lugares están libres y cuáles ocupados.','¿Sabe en todo momento qué lugares o espacios están libres y cuáles ocupados?','confirmada'),
('nec-no-coordina-recursos-simultaneos','No coordina recursos entre eventos simultáneos','Personal e insumos repartidos parejo aunque la demanda de cada sala sea distinta.','¿Cuando hay varios eventos o salas al mismo tiempo, reparte personal e insumos a ojo?','confirmada')
on conflict (clave) do update set nombre=excluded.nombre,descripcion=excluded.descripcion,pregunta_confirmacion=excluded.pregunta_confirmacion;

